<?php
$eyebrow = get_sub_field( 'eyebrow' ); $heading = get_sub_field( 'heading' ); $description = get_sub_field( 'description' ); $items = di_service_v2_rows( get_sub_field( 'items' ) );
$schema = 'yes' === get_sub_field( 'enable_schema' ) && ! defined( 'AIOSEO_VERSION' ); $background = get_sub_field( 'background' ); if ( ! $eyebrow && ! $heading && ! $description && ! $items ) { return; }
?>
<?php $uid = 'service-faq-' . absint( get_the_ID() ) . '-' . absint( get_row_index() ); ?>
<section class="faq-wrp padding_top_bottom service-v2-faqs <?php echo esc_attr( di_service_v2_background_class( $background ) ); ?>"><div class="container"><div class="faq-text"><div class="heading"><?php if ( $eyebrow ) : ?><p class="service-v2-kicker"><?php echo esc_html( $eyebrow ); ?></p><?php endif; ?><?php if ( $heading ) : ?><h2><?php echo esc_html( $heading ); ?></h2><?php endif; ?><?php if ( $description ) : ?><div class="sub_pera"><?php echo wp_kses_post( wpautop( $description ) ); ?></div><?php endif; ?></div></div>
	<?php if ( $items ) : ?><div class="row justify-content-center"><div class="col-lg-7 col-sm-8"><div class="accordion" id="<?php echo esc_attr( $uid ); ?>"><?php foreach ( $items as $index => $item ) : ?><div class="accordion-item"><h3 class="accordion-header"><button class="accordion-button<?php echo 0 === $index ? '' : ' collapsed'; ?>" type="button" data-bs-toggle="collapse" data-bs-target="#<?php echo esc_attr( $uid . '-' . $index ); ?>"><?php echo esc_html( $item['question'] ?? '' ); ?></button></h3><div id="<?php echo esc_attr( $uid . '-' . $index ); ?>" class="accordion-collapse collapse<?php echo 0 === $index ? ' show' : ''; ?>" data-bs-parent="#<?php echo esc_attr( $uid ); ?>"><div class="accordion-body"><?php echo wp_kses_post( $item['answer'] ?? '' ); ?></div></div></div><?php endforeach; ?></div></div></div><?php endif; ?></div>
</section>
<?php if ( $schema && $items ) : $entities = array(); foreach ( $items as $item ) { if ( ! empty( $item['question'] ) && ! empty( $item['answer'] ) ) { $entities[] = array('@type' => 'Question', 'name' => wp_strip_all_tags( $item['question'] ), 'acceptedAnswer' => array('@type' => 'Answer', 'text' => wp_strip_all_tags( $item['answer'] ))); } } if ( $entities ) : ?><script type="application/ld+json"><?php echo wp_json_encode( array('@context' => 'https://schema.org', '@type' => 'FAQPage', 'mainEntity' => $entities), JSON_UNESCAPED_SLASHES | JSON_UNESCAPED_UNICODE ); // phpcs:ignore ?></script><?php endif; endif; ?>
